static const bitmap_t asset_go = {
    56,
    56,
    asset_go_pixels,
};

const bitmap_t* assets_piece_bitmap(piece_type_t type) {
    switch (type) {
        case PIECE_KING:
            return &asset_c;
        case PIECE_QUEEN:
            return &asset_java;
        case PIECE_BISHOP:
            return &asset_python;
        case PIECE_KNIGHT:
            return &asset_javascript;
        case PIECE_ROOK:
            return &asset_rust;
        case PIECE_PAWN:
            return &asset_go;
        case PIECE_NONE:
        default:
            return 0;
    }
}
